-- Frozen SQLite baseline. Future schema changes require a new revision.
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY, file_path VARCHAR(255) NOT NULL, file_type VARCHAR(50) NOT NULL, attachable_type VARCHAR(50) NOT NULL, attachable_id BIGINT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS directorates (id INTEGER PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL DEFAULT '', location VARCHAR(500) NOT NULL DEFAULT '', is_active BOOLEAN NOT NULL DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permissions (code VARCHAR(80) PRIMARY KEY NOT NULL, name VARCHAR(150) NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT NOT NULL DEFAULT '', is_system BOOLEAN NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, first_name VARCHAR(100), last_name VARCHAR(100), phone VARCHAR(20) UNIQUE, email VARCHAR(254) UNIQUE, username VARCHAR(50) UNIQUE, hashed_password VARCHAR(255), user_type VARCHAR(20) NOT NULL CHECK(user_type IN ('citizen','employee')), is_active BOOLEAN NOT NULL DEFAULT 1, needs_profile_completion BOOLEAN NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS citizens (id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE REFERENCES users(id), first_name VARCHAR(50) NOT NULL, last_name VARCHAR(50) NOT NULL, phone VARCHAR(20) NOT NULL UNIQUE, national_id VARCHAR(20) NOT NULL UNIQUE, telegram_id BIGINT UNIQUE, identity_card_url VARCHAR(255), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees (id BIGINT PRIMARY KEY NOT NULL, user_id INTEGER UNIQUE REFERENCES users(id), rbac_initialized BOOLEAN NOT NULL DEFAULT 0, full_name VARCHAR(100) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, hashed_password VARCHAR(255) NOT NULL, role VARCHAR(8) NOT NULL, is_demo BOOLEAN NOT NULL DEFAULT 0, password_version INTEGER NOT NULL DEFAULT 1, directorate_id BIGINT REFERENCES directorates(id), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_code VARCHAR(80) NOT NULL REFERENCES permissions(code) ON DELETE RESTRICT, PRIMARY KEY(role_id,permission_code));
CREATE TABLE IF NOT EXISTS access_audit (id INTEGER PRIMARY KEY, actor_id BIGINT NOT NULL REFERENCES employees(id) ON DELETE RESTRICT, action VARCHAR(80) NOT NULL, target_type VARCHAR(40) NOT NULL, target_id VARCHAR(80) NOT NULL, details TEXT NOT NULL DEFAULT '', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS citizen_ownership_challenges (digest VARCHAR(64) PRIMARY KEY NOT NULL, citizen_id INTEGER NOT NULL REFERENCES citizens(id), purpose VARCHAR(16) NOT NULL, browser_digest VARCHAR(64), expected_telegram_id BIGINT, expires_at BIGINT NOT NULL, approved BOOLEAN NOT NULL, consumed BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS citizen_recovery_keys (citizen_id INTEGER PRIMARY KEY REFERENCES citizens(id), digest VARCHAR(64) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS complaints (id INTEGER PRIMARY KEY, tracking_code VARCHAR(30) NOT NULL UNIQUE, citizen_id BIGINT NOT NULL REFERENCES citizens(id), directorate_id BIGINT NOT NULL REFERENCES directorates(id), title VARCHAR(150) NOT NULL, details TEXT NOT NULL, category VARCHAR(50) NOT NULL, is_public BOOLEAN NOT NULL DEFAULT 0, public_text_hidden BOOLEAN NOT NULL DEFAULT 0, priority VARCHAR(6) NOT NULL, status VARCHAR(11) NOT NULL, latitude FLOAT, longitude FLOAT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME, progress INTEGER NOT NULL DEFAULT 0, resolution_report TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS employee_role_assignments (id INTEGER PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id) ON DELETE RESTRICT, role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, scope_type VARCHAR(20) NOT NULL, directorate_id INTEGER REFERENCES directorates(id) ON DELETE RESTRICT, scope_key INTEGER NOT NULL, UNIQUE(employee_id,role_id,scope_key), CHECK((scope_type='global' AND directorate_id IS NULL AND scope_key=0) OR (scope_type='directorate' AND directorate_id IS NOT NULL AND directorate_id>0 AND scope_key=directorate_id)));
CREATE TABLE IF NOT EXISTS complaint_notes (id INTEGER PRIMARY KEY, complaint_id BIGINT NOT NULL REFERENCES complaints(id), author_id BIGINT NOT NULL REFERENCES employees(id), note TEXT NOT NULL, is_internal BOOLEAN NOT NULL, audience VARCHAR(20) NOT NULL DEFAULT 'private', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, notification_status VARCHAR(30) NOT NULL DEFAULT 'not_requested', notification_error TEXT);
CREATE TABLE IF NOT EXISTS evidence_requests (id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id), author_id BIGINT NOT NULL REFERENCES employees(id), prompt TEXT NOT NULL, submission_key VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, notification_status VARCHAR(30) NOT NULL, notification_error TEXT, notification_attempted_at INTEGER NOT NULL, UNIQUE(complaint_id,submission_key));
CREATE TABLE IF NOT EXISTS public_complaint_reviews (id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id), author_id BIGINT NOT NULL REFERENCES employees(id), action VARCHAR(20) NOT NULL, reason TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, notification_status VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_replies (id INTEGER PRIMARY KEY, request_id INTEGER NOT NULL UNIQUE REFERENCES evidence_requests(id), submission_key VARCHAR(80) NOT NULL, payload_digest VARCHAR(64) NOT NULL, text TEXT NOT NULL, channel VARCHAR(20) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public_complaint_reports (id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id), reason TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, review_id INTEGER REFERENCES public_complaint_reviews(id));
CREATE TABLE IF NOT EXISTS evidence_files (id INTEGER PRIMARY KEY, reply_id INTEGER NOT NULL REFERENCES evidence_replies(id), file_path VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, file_type VARCHAR(50) NOT NULL);
